import {
  Component, ElementRef, afterEveryRender, effect, input, output, signal, viewChild, viewChildren,
} from '@angular/core';
import { TablerIconComponent, IconDotsVertical } from '@tabler/icons-angular';
import { NzDropDownModule } from 'ng-zorro-antd/dropdown';
import { NzMenuModule } from 'ng-zorro-antd/menu';
import { HrmButton } from '../general/hrm-button';

/** 1 hành động trên action bar. tone = màu nút (primary xanh brand · error đỏ · warning vàng ·
 *  violet tím · neutral mặc định). danger = tô đỏ khi nằm trong menu ⋮. */
export interface HrmActionBarItem {
  key: string;
  label: string;
  icon?: unknown;
  tone?: 'primary' | 'neutral' | 'error' | 'warning' | 'violet' | 'success' | 'info';
  danger?: boolean;
}

/** hrm-action-bar — hàng nút hành động KHÔNG rớt hàng (responsive): đo bề rộng thanh + nút, nút DƯ
 *  ẩn dần vào nút ⋮ (more) ở GÓC PHẢI. Dùng cho footer chi tiết / toolbar khi số nút có thể vượt
 *  bề rộng. Bấm phát (action)=key (cả nút hiện lẫn mục trong menu). Toàn token → tự Light/Dark.
 *
 *   <hrm-action-bar [actions]="acts" moreLabel="Thêm thao tác" (action)="run($event)" /> */
@Component({
  selector: 'hrm-action-bar',
  imports: [HrmButton, TablerIconComponent, NzDropDownModule, NzMenuModule],
  template: `
    <div class="ab" #bar>
      @for (a of actions(); track a.key; let i = $index) {
        <hrm-button #btn [variant]="a.tone === 'neutral' ? 'default' : 'primary'" size="md"
          [attr.data-tone]="a.tone" [hidden]="i >= visibleCount()" (click)="action.emit(a.key)">
          @if (a.icon) { <tabler-icon [icon]="$any(a.icon)" [size]="15" /> }
          {{ a.label }}
        </hrm-button>
      }
      @if (visibleCount() < actions().length) {
        <button type="button" class="ab-more" [attr.aria-label]="moreLabel() || null"
          nz-dropdown [nzDropdownMenu]="moreMenu" nzTrigger="click" nzPlacement="bottomRight">
          <tabler-icon [icon]="icMore" [size]="16" />
        </button>
        <nz-dropdown-menu #moreMenu="nzDropdownMenu">
          <ul nz-menu class="ab-menu">
            @for (a of actions(); track a.key; let i = $index) {
              @if (i >= visibleCount()) {
                <li nz-menu-item [class.ab-mi-danger]="a.danger || a.tone === 'error'" (click)="action.emit(a.key)">
                  @if (a.icon) { <tabler-icon [icon]="$any(a.icon)" [size]="16" /> }
                  {{ a.label }}
                </li>
              }
            }
          </ul>
        </nz-dropdown-menu>
      }
    </div>
  `,
  host: { class: 'hrm-action-bar' },
  styles: [`
    :host { display: block; min-width: 0; width: 100%; }
    /* Hàng nút — KHÔNG rớt hàng (nowrap); nút dư ẩn vào ⋮ đẩy về góc phải. */
    .ab { display: flex; align-items: center; gap: var(--space-2); flex-wrap: nowrap; min-width: 0; width: 100%; }
    hrm-button[hidden] { display: none; }
    hrm-button tabler-icon { margin-right: var(--space-0-5); }
    hrm-button ::ng-deep .ant-btn { padding-inline: var(--space-2); gap: var(--space-0-5); white-space: nowrap; }

    /* Nút ⋮ more — GÓC PHẢI (margin-left auto đẩy về cuối hàng). */
    .ab-more {
      margin-left: auto; flex: none; display: inline-flex; align-items: center; justify-content: center;
      width: 34px; height: 34px; border: 1px solid var(--border-sub); background: var(--bg-surface);
      border-radius: var(--radius-md); cursor: pointer; color: var(--text-sub);
      transition: border-color var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease);
    }
    .ab-more:hover { border-color: var(--primary-base); color: var(--text-strong); }

    /* Tông màu nút (nền đặc) theo ngữ nghĩa — đồng bộ hrm-workflow-actions. */
    hrm-button[data-tone='error'] ::ng-deep .ant-btn { background: var(--error-base); border-color: var(--error-base); color: var(--static-white, #fff); }
    hrm-button[data-tone='error'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    hrm-button[data-tone='warning'] ::ng-deep .ant-btn { background: var(--warning-base); border-color: var(--warning-base); color: var(--static-white, #fff); }
    hrm-button[data-tone='warning'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    hrm-button[data-tone='violet'] ::ng-deep .ant-btn { background: var(--purple-500); border-color: var(--purple-500); color: var(--static-white, #fff); }
    hrm-button[data-tone='violet'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    :host ::ng-deep .ab-menu .ant-dropdown-menu-item { display: flex; align-items: center; gap: 8px; }
    .ab-mi-danger { color: var(--error-base); }
  `],
})
export class HrmActionBar {
  /** Danh sách hành động (thứ tự trái→phải; nút cuối ẩn vào ⋮ trước khi hẹp). */
  readonly actions = input<HrmActionBarItem[]>([]);
  /** Nhãn a11y nút ⋮ (i18n). */
  readonly moreLabel = input('');
  /** Phát key hành động khi bấm (nút hiện hoặc mục trong menu ⋮). */
  readonly action = output<string>();

  protected readonly icMore = IconDotsVertical;

  private readonly bar = viewChild<ElementRef<HTMLElement>>('bar');
  private readonly btns = viewChildren('btn', { read: ElementRef });
  /** Số nút hiện trên hàng (còn lại thu vào ⋮). Mặc định lớn → render hết để đo. */
  protected readonly visibleCount = signal(99);
  private widths: number[] = [];

  constructor() {
    // Đổi bộ hành động → render lại toàn bộ để đo lại bề rộng.
    effect(() => { this.actions(); this.widths = []; this.visibleCount.set(99); });
    // Sau mỗi render (kể cả resize): tính số nút vừa hàng, dư vào ⋮.
    afterEveryRender(() => this.recompute());
  }

  /** Đo bề rộng nút + so bề rộng thanh → set số nút hiển thị; phần dư vào ⋮. */
  private recompute(): void {
    const bar = this.bar()?.nativeElement;
    const btns = this.btns();
    if (!bar || !btns.length) return;
    btns.forEach((b, i) => { const w = (b.nativeElement as HTMLElement).offsetWidth; if (w > 0) this.widths[i] = w; });
    const n = this.actions().length;
    const gap = 8, moreW = 34 + gap;
    const avail = bar.clientWidth;
    const full = this.widths.slice(0, n).reduce((s, w, i) => s + (w || 0) + (i ? gap : 0), 0);
    let count: number;
    if (full <= avail) {
      count = n;
    } else {
      let used = 0; count = 0;
      for (let i = 0; i < n; i++) {
        const w = (this.widths[i] || 0) + (i ? gap : 0);
        if (used + w + moreW > avail) break;
        used += w; count++;
      }
      count = Math.max(1, count);
    }
    this.visibleCount.set(count);
  }
}
